grid=[[int(v) for v in row.split()] for row in m.group(1).splitlines()]
# fill 1-valued marker cells from the most common non-1 orthogonal/nearby color, then rotate CCW
import collections
filled=[r[:] for r in grid]
for i in range(30):
 for j in range(30):
  if grid[i][j]==1:
   vals=[]
   for di,dj in [(0,1),(1,0),(0,-1),(-1,0),(0,2),(2,0),(0,-2),(-2,0)]:
    a,b=i+di,j+dj
    if 0<=a<30 and 0<=b<30 and grid[a][b]!=1: vals.append(grid[a][b])
   if vals: filled[i][j]=collections.Counter(vals).most_common(1)[0][0]
out=[[filled[i][j] for i in range(30)] for j in range(29,-1,-1)]
print(len(out),out[0])
